class ConvPool(nn.Module):
    def __init__(self, in_ch, out_ch, ks, pool):
        super().__init__()
        self.conv = nn.Conv1d(in_ch, out_ch, ks, padding="same", bias=False)
        self.bn = nn.BatchNorm1d(out_ch)
        self.pool = pool

    def forward(self, x):
        return self.pool(F.relu(self.bn(self.conv(x))))


class Branch(nn.Module):
    def __init__(self, in_dim, hidden=140, dropout=0.3):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden, bias=False), nn.BatchNorm1d(hidden), nn.ReLU(), nn.Dropout(dropout),
            nn.Linear(hidden, hidden, bias=False), nn.BatchNorm1d(hidden), nn.ReLU(),
            nn.Linear(hidden, 1))

    def forward(self, x):
        return self.net(x)


class BranchedBasset(nn.Module):
    def __init__(self, n_outputs=3, in_ch=4, bins=8, shared_dim=1000, branch_dim=140, dropout=0.3):
        super().__init__()
        self.trunk = nn.Sequential(
            ConvPool(in_ch, 300, 19, nn.MaxPool1d(3)),
            ConvPool(300, 200, 11, nn.MaxPool1d(4)),
            ConvPool(200, 200, 7, nn.AdaptiveMaxPool1d(bins)))
        self.shared = nn.Sequential(
            nn.Flatten(),
            nn.Linear(200 * bins, shared_dim, bias=False), nn.BatchNorm1d(shared_dim), nn.ReLU(), nn.Dropout(dropout))
        self.branches = nn.ModuleList([Branch(shared_dim, branch_dim, dropout) for _ in range(n_outputs)])

    def forward(self, x):
        h = self.shared(self.trunk(x))
        return torch.cat([b(h) for b in self.branches], dim=1)


def build_model(n_outputs=3):
    return BranchedBasset(n_outputs=n_outputs)

