# --- block: data_handling ---
def prepare_training_data(y, se, meta):
    """Per-cell inverse-variance weights with a variance floor, packed as extra target columns."""
    y = np.asarray(y, np.float32)
    se = np.asarray(se, np.float32).copy()
    keep = np.isfinite(y).all(axis=1)
    for j in range(se.shape[1]):
        col = se[:, j]
        bad = ~np.isfinite(col) | (col <= 0)
        med = np.nanmedian(np.where(bad, np.nan, col))
        col[bad] = med
        se[:, j] = col
    floor = PARAMS.get("se_var_floor", 0.05)
    w = 1.0 / (se ** 2 + floor)
    w = w / w[keep].mean(axis=0, keepdims=True)
    w = np.clip(w, 0.0, PARAMS.get("w_clip", 5.0))
    w = w / w[keep].mean(axis=0, keepdims=True)
    targets = np.concatenate([y, w.astype(np.float32)], axis=1).astype(np.float32)
    weights = np.ones(len(y), np.float32)
    return keep, targets, weights, lambda p: p

