class TBlock(nn.Module):
    """Pre-LN transformer block with layer-scale on both residual branches."""
    def __init__(self, d, heads, ff_mult=4, dropout=0.1, ls_init=0.1):
        super().__init__()
        self.ln1 = nn.LayerNorm(d)
        self.attn = nn.MultiheadAttention(d, heads, dropout=dropout, batch_first=True)
        self.ln2 = nn.LayerNorm(d)
        self.ff = nn.Sequential(nn.Linear(d, d * ff_mult), nn.GELU(), nn.Dropout(dropout),
                                nn.Linear(d * ff_mult, d))
        self.drop = nn.Dropout(dropout)
        self.g1 = nn.Parameter(torch.full((d,), ls_init))
        self.g2 = nn.Parameter(torch.full((d,), ls_init))

    def forward(self, x):
        h = self.ln1(x)
        a, _ = self.attn(h, h, h, need_weights=False)
        x = x + self.g1 * self.drop(a)
        x = x + self.g2 * self.drop(self.ff(self.ln2(x)))
        return x


class ConvTransformer(nn.Module):
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=64, stem_ks=11, ef_ks=9,
                 conv_sizes=(96, 128), pool_sizes=(2, 2), resize_factor=4,
                 d_model=192, n_heads=8, n_layers=4, max_len=256, dropout=0.1,
                 activation=nn.SiLU):
        super().__init__()
        self.stem = LocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for pool, out_ch in zip(pool_sizes, conv_sizes):
            blocks.append(nn.Sequential(
                ResidualConcat(EffBlock(ch, ef_ks, resize_factor, activation)),
                LocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(pool) if pool != 1 else nn.Identity()))
            ch = out_ch
        self.conv = nn.Sequential(*blocks)
        self.proj = nn.Conv1d(ch, d_model, 1)
        self.pos = nn.Parameter(torch.zeros(1, max_len, d_model))
        nn.init.normal_(self.pos, std=0.02)
        self.layers = nn.ModuleList([TBlock(d_model, n_heads, 4, dropout) for _ in range(n_layers)])
        self.norm = nn.LayerNorm(d_model)
        self.head = nn.Sequential(
            nn.Linear(d_model, d_model), nn.SiLU(), nn.Dropout(dropout),
            nn.Linear(d_model, n_outputs))

    def forward(self, x):
        x = self.proj(self.conv(self.stem(x)))  # (B, d, L)
        x = x.transpose(1, 2)  # (B, L, d)
        L = x.shape[1]
        if L <= self.pos.shape[1]:
            pos = self.pos[:, :L]
        else:
            pos = F.interpolate(self.pos.transpose(1, 2), size=L, mode="linear", align_corners=False).transpose(1, 2)
        x = x + pos
        for layer in self.layers:
            x = layer(x)
        x = self.norm(x).mean(dim=1)
        return self.head(x)


