class PairLegNet(nn.Module):
    """One LegNet. With an 8-channel input (main one-hot, partner one-hot; partner all-zero when
    absent), the same network also predicts the partner rows that exist; those predictions are
    left in torch._evoloop_pair_pred for the loss. Output is always (B, n_outputs) for the main rows."""
    def __init__(self, n_outputs=3):
        super().__init__()
        self.net = LegNet(n_outputs=n_outputs)

    def forward(self, x):
        torch._evoloop_pair_pred = None
        if x.shape[1] == 8:
            main_x = x[:, :4]
            part_x = x[:, 4:]
            has = part_x.sum(dim=(1, 2)) > 0
            idx = torch.nonzero(has).squeeze(1)
            b = main_x.shape[0]
            if idx.numel() > 0:
                out = self.net(torch.cat([main_x, part_x[idx]], dim=0))
                torch._evoloop_pair_pred = out[b:]
                return out[:b]
            return self.net(main_x)
        return self.net(x)


