# --- block: optimizer ---
def make_optimizer(model, steps_per_epoch, max_epochs):
    """Returns (optimizer, step_fn called after every batch, epoch_fn(val_score) called after every epoch).
    Keeps an EMA of the weights (and float buffers); the EMA is loaded into the model at the end of
    each epoch so validation and best-checkpointing use it, and the raw weights are restored after."""
    opt = torch.optim.AdamW(model.parameters(), lr=PARAMS["lr"], weight_decay=PARAMS["weight_decay"])
    warm = max(1, int(PARAMS["warmup_epochs"] * steps_per_epoch))
    spe = max(1, int(steps_per_epoch))
    state = {"step": 0, "n_ema": 0, "raw": None}
    plateau = torch.optim.lr_scheduler.ReduceLROnPlateau(
        opt, mode="max", factor=PARAMS["plateau_factor"], patience=PARAMS["plateau_patience"])
    base_decay = float(PARAMS.get("ema_decay", 0.999))
    sd = model.state_dict()
    ema_keys = [k for k, v in sd.items() if torch.is_floating_point(v)]
    other_keys = [k for k, v in sd.items() if not torch.is_floating_point(v)]
    with torch.no_grad():
        ema = {k: sd[k].detach().clone().float() for k in ema_keys}

    def _restore_raw():
        if state["raw"] is not None:
            cur = model.state_dict()
            with torch.no_grad():
                for k, v in state["raw"].items():
                    cur[k].copy_(v)
            state["raw"] = None

    def _load_ema():
        cur = model.state_dict()
        with torch.no_grad():
            state["raw"] = {k: cur[k].detach().clone() for k in ema_keys + other_keys}
            for k in ema_keys:
                cur[k].copy_(ema[k].to(cur[k].dtype))

    def step_fn():
        # Safety: if the EMA was still loaded (missed epoch_fn), put raw weights back first.
        _restore_raw()
        state["step"] += 1
        if state["step"] <= warm:
            for g in opt.param_groups:
                g["lr"] = PARAMS["lr"] * state["step"] / warm
        state["n_ema"] += 1
        n = state["n_ema"]
        d = min(base_decay, (1.0 + n) / (10.0 + n))
        cur = model.state_dict()
        with torch.no_grad():
            for k in ema_keys:
                ema[k].mul_(d).add_(cur[k].detach().float(), alpha=1.0 - d)
        if state["step"] % spe == 0:
            _load_ema()

    def epoch_fn(val_score):
        _restore_raw()
        if state["step"] > warm:
            plateau.step(val_score)

    return opt, step_fn, epoch_fn

