class ConvBiGRU(nn.Module):
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=96, stem_ks=11, ef_ks=9,
                 stage_sizes=(160, 192), resize_factor=4, rnn_hidden=128, rnn_layers=2,
                 activation=nn.SiLU):
        super().__init__()
        self.stem = LocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for out_ch in stage_sizes:
            blocks.append(nn.Sequential(
                ResidualConcat(EffBlock(ch, ef_ks, resize_factor, activation)),
                LocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(2)))
            ch = out_ch
        self.main = nn.Sequential(*blocks)
        self.norm = nn.LayerNorm(ch)
        self.rnn = nn.GRU(ch, rnn_hidden, num_layers=rnn_layers, batch_first=True,
                          bidirectional=True, dropout=0.1)
        self.proj = nn.Linear(2 * rnn_hidden, ch)
        self.out_norm = nn.LayerNorm(ch)
        d = 2 * ch
        self.head = nn.Sequential(
            nn.Linear(d, d), nn.BatchNorm1d(d), activation(),
            nn.Linear(d, n_outputs))

    def forward(self, x):
        h = self.main(self.stem(x))            # (B, C, L)
        h = h.transpose(1, 2)                  # (B, L, C)
        with torch.autocast(device_type=h.device.type, enabled=False):
            hf = h.float()
            r, _ = self.rnn(self.norm(hf))
            hf = self.out_norm(hf + self.proj(r))
        feat = torch.cat([hf.mean(dim=1), hf.amax(dim=1)], dim=1)
        return self.head(feat)


