        self.fn = fn

    def forward(self, x):
        return torch.cat([self.fn(x), x], dim=1)


class CellBranch(nn.Module):
    def __init__(self, in_dim, hidden, activation):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden), nn.BatchNorm1d(hidden), activation(),
            nn.Linear(hidden, 1))

    def forward(self, x):
        return self.net(x)


class BranchedLegNet(nn.Module):
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=64, stem_ks=11, ef_ks=9,
                 ef_block_sizes=(128, 160, 192, 256), pool_sizes=(2, 2, 2, 2), resize_factor=4,
                 branch_hidden=256, activation=nn.SiLU):
        super().__init__()
        self.stem = LocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for pool, out_ch in zip(pool_sizes, ef_block_sizes):
            blocks.append(nn.Sequential(
                ResidualConcat(EffBlock(ch, ef_ks, resize_factor, activation)),
                LocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(pool) if pool != 1 else nn.Identity()))
            ch = out_ch
        self.main = nn.Sequential(*blocks)
        self.mapper = nn.Sequential(nn.Conv1d(ch, ch * 2, 1, bias=False), nn.BatchNorm1d(ch * 2), activation())
        self.branches = nn.ModuleList([CellBranch(ch * 2, branch_hidden, activation) for _ in range(n_outputs)])

    def forward(self, x):
        h = self.mapper(self.main(self.stem(x)))
        h = F.adaptive_avg_pool1d(h, 1).squeeze(-1)
        return torch.cat([b(h) for b in self.branches], dim=1)


class PairLegNet(nn.Module):
    """One network. With an 8-channel input (main one-hot, partner one-hot; partner all-zero when
    absent), partner rows that exist are run in a separate forward pass (so main-row BatchNorm
    statistics are not pair-biased); their predictions go to torch._evoloop_pair_pred for the loss."""
    def __init__(self, n_outputs=3):
        super().__init__()
        self.net = BranchedLegNet(n_outputs=n_outputs)

    def forward(self, x):
        torch._evoloop_pair_pred = None
        if x.shape[1] == 8:
            main_x = x[:, :4]
            part_x = x[:, 4:]
            out = self.net(main_x)
            has = part_x.sum(dim=(1, 2)) > 0
            idx = torch.nonzero(has).squeeze(1)
            if idx.numel() >= 2:
                torch._evoloop_pair_pred = self.net(part_x[idx])
            return out
        return self.net(x)


