_BN_MODE = {"mode": None}


class PairBN(nn.BatchNorm1d):
    """BatchNorm1d that, in training, can record the batch statistics of one pass (mode 'record')
    and normalise a later pass with them (mode 'reuse') without touching running statistics."""
    def __init__(self, n):
        super().__init__(n)
        self._cache = None

    def forward(self, x):
        mode = _BN_MODE["mode"]
        if not self.training or mode is None:
            return super().forward(x)
        if mode == "reuse" and self._cache is not None:
            mean, var = self._cache
            xf = x.float()
            if xf.dim() == 3:
                return ((xf - mean[None, :, None]) * torch.rsqrt(var[None, :, None] + self.eps)
                        * self.weight[None, :, None] + self.bias[None, :, None])
            return (xf - mean[None]) * torch.rsqrt(var[None] + self.eps) * self.weight[None] + self.bias[None]
        xf = x.float()
        dims = (0, 2) if xf.dim() == 3 else (0,)
        self._cache = (xf.mean(dim=dims), xf.var(dim=dims, unbiased=False))
        return super().forward(x)


class SELayer(nn.Module):
    def __init__(self, inp, oup, reduction=4):
        super().__init__()
        self.fc = nn.Sequential(
            nn.Linear(oup, inp // reduction), nn.SiLU(),
            nn.Linear(inp // reduction, oup), nn.Sigmoid())

    def forward(self, x):
        y = self.fc(x.mean(dim=2))
        return x * y.unsqueeze(-1)


class EffBlock(nn.Module):
    def __init__(self, in_ch, ks, resize_factor, activation):
        super().__init__()
        mid = in_ch * resize_factor
        self.block = nn.Sequential(
            nn.Conv1d(in_ch, mid, 1, bias=False), PairBN(mid), activation(),
            nn.Conv1d(mid, mid, ks, groups=mid, padding="same", bias=False), PairBN(mid), activation(),
            SELayer(in_ch, mid, reduction=4),
            nn.Conv1d(mid, in_ch, 1, bias=False), PairBN(in_ch), activation())

    def forward(self, x):
        return self.block(x)


class LocalBlock(nn.Module):
    def __init__(self, in_ch, out_ch, ks, activation):
        super().__init__()
        self.block = nn.Sequential(
            nn.Conv1d(in_ch, out_ch, ks, padding="same", bias=False), PairBN(out_ch), activation())

    def forward(self, x):
        return self.block(x)


class ResidualConcat(nn.Module):
    def __init__(self, fn):
        super().__init__()
        self.fn = fn

    def forward(self, x):
        return torch.cat([self.fn(x), x], dim=1)


class LegNet(nn.Module):
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=64, stem_ks=11, ef_ks=9,
                 ef_block_sizes=(128, 160, 192, 256), pool_sizes=(2, 2, 2, 2), resize_factor=4,
                 activation=nn.SiLU):
        super().__init__()
        self.stem = LocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for pool, out_ch in zip(pool_sizes, ef_block_sizes):
            blocks.append(nn.Sequential(
                ResidualConcat(EffBlock(ch, ef_ks, resize_factor, activation)),
                LocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(pool) if pool != 1 else nn.Identity()))
            ch = out_ch
        self.main = nn.Sequential(*blocks)
        self.mapper = nn.Sequential(nn.Conv1d(ch, ch * 2, 1, bias=False), PairBN(ch * 2), activation())
        self.head = nn.Sequential(
            nn.Linear(ch * 2, ch * 2), PairBN(ch * 2), activation(),
            nn.Linear(ch * 2, n_outputs))

    def forward(self, x):
        x = self.mapper(self.main(self.stem(x)))
        return self.head(F.adaptive_avg_pool1d(x, 1).squeeze(-1))


class PairLegNet(nn.Module):
    """One LegNet. With an 8-channel training input (main one-hot, partner one-hot; partner all-zero
    when absent), main rows run first and set the BatchNorm batch statistics; partner rows then run
    through the same weights normalised by the main rows' statistics (no running-stat update).
    Partner predictions go to torch._evoloop_pair_pred for the loss."""
    def __init__(self, n_outputs=3):
        super().__init__()
        self.net = LegNet(n_outputs=n_outputs)

    def _clear(self):
        for m in self.net.modules():
            if isinstance(m, PairBN):
                m._cache = None

    def forward(self, x):
        torch._evoloop_pair_pred = None
        if x.shape[1] == 8:
            main_x = x[:, :4]
            part_x = x[:, 4:]
            if not self.training:
                return self.net(main_x)
            has = part_x.sum(dim=(1, 2)) > 0
            idx = torch.nonzero(has).squeeze(1)
            try:
                if idx.numel() > 0:
                    _BN_MODE["mode"] = "record"
                    out = self.net(main_x)
                    _BN_MODE["mode"] = "reuse"
                    torch._evoloop_pair_pred = self.net(part_x[idx])
                else:
                    _BN_MODE["mode"] = None
                    out = self.net(main_x)
            finally:
                _BN_MODE["mode"] = None
                self._clear()
            return out
        return self.net(x)


def build_model(n_outputs=3):
    return PairLegNet(n_outputs=n_outputs)

