import math
import torch
import torch.nn as nn
import torch.nn.functional as F


# Reverse-complement parameter sharing (RCPS). Representation layout: 2C channels where the
# reverse complement of a feature map h is h.flip(1).flip(2) (channel c pairs with 2C-1-c), the
# same convention as one-hot ACGT input. Every layer below is equivariant under that operation.

class RCConv(nn.Module):
    def __init__(self, cin, cout, ks, bias=False):
        super().__init__()
        assert cin % 2 == 0 and cout % 2 == 0
        self.weight = nn.Parameter(torch.empty(cout // 2, cin, ks))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.bias = nn.Parameter(torch.zeros(cout // 2)) if bias else None
        self.pad = ks // 2

    def forward(self, x):
        w = torch.cat([self.weight, self.weight.flip(0, 1, 2)], 0)
        b = None
        if self.bias is not None:
            b = torch.cat([self.bias, self.bias.flip(0)], 0)
        return F.conv1d(x, w, b, padding=self.pad)


class RCDepthwise(nn.Module):
    def __init__(self, ch, ks):
        super().__init__()
        assert ch % 2 == 0
        self.ch = ch
        self.weight = nn.Parameter(torch.empty(ch // 2, 1, ks))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        self.pad = ks // 2

    def forward(self, x):
        w = torch.cat([self.weight, self.weight.flip(0, 2)], 0)
        return F.conv1d(x, w, None, padding=self.pad, groups=self.ch)


class RCBN(nn.Module):
    """BatchNorm with statistics and affine parameters tied between channel c and 2C-1-c."""
    def __init__(self, ch):
        super().__init__()
        self.c = ch // 2
        self.bn = nn.BatchNorm1d(self.c)

    def forward(self, x):
        b = x.shape[0]
        a = x[:, :self.c]
        r = x[:, self.c:].flip(1)
        z = self.bn(torch.cat([a, r], 0))
        a, r = z[:b], z[b:]
        return torch.cat([a, r.flip(1)], 1)


def rc_cat(a, b):
    ca = a.shape[1] // 2
    cb = b.shape[1] // 2
    return torch.cat([a[:, :ca], b[:, :cb], b[:, cb:], a[:, ca:]], 1)


class RCSE(nn.Module):
    def __init__(self, inp, oup, reduction=4):
        super().__init__()
        h = max(2, (inp // reduction) // 2 * 2)
        self.fc1 = RCConv(oup, h, 1, bias=True)
        self.fc2 = RCConv(h, oup, 1, bias=True)

    def forward(self, x):
        s = x.mean(dim=2, keepdim=True)
        g = torch.sigmoid(self.fc2(F.silu(self.fc1(s))))
        return x * g


class RCEffBlock(nn.Module):
    def __init__(self, in_ch, ks, resize_factor, activation):
        super().__init__()
        mid = in_ch * resize_factor
        self.block = nn.Sequential(
            RCConv(in_ch, mid, 1), RCBN(mid), activation(),
            RCDepthwise(mid, ks), RCBN(mid), activation(),
            RCSE(in_ch, mid, reduction=4),
            RCConv(mid, in_ch, 1), RCBN(in_ch), activation())

    def forward(self, x):
        return self.block(x)


class RCLocalBlock(nn.Module):
    def __init__(self, in_ch, out_ch, ks, activation):
        super().__init__()
        self.block = nn.Sequential(RCConv(in_ch, out_ch, ks), RCBN(out_ch), activation())

    def forward(self, x):
        return self.block(x)


class RCResidualConcat(nn.Module):
    def __init__(self, fn):
        super().__init__()
        self.fn = fn

    def forward(self, x):
        return rc_cat(self.fn(x), x)


class RCLegNet(nn.Module):
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=96, stem_ks=11, ef_ks=9,
                 ef_block_sizes=(160, 192, 256, 320), pool_sizes=(2, 2, 2, 2), resize_factor=4,
                 activation=nn.SiLU):
        super().__init__()
        self.stem = RCLocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for pool, out_ch in zip(pool_sizes, ef_block_sizes):
            blocks.append(nn.Sequential(
                RCResidualConcat(RCEffBlock(ch, ef_ks, resize_factor, activation)),
                RCLocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(pool) if pool != 1 else nn.Identity()))
            ch = out_ch
        self.main = nn.Sequential(*blocks)
        self.mapper = nn.Sequential(RCConv(ch, ch * 2, 1), RCBN(ch * 2), activation())
        c = ch  # invariant feature size: half of the mapper's 2*ch channels
        self.c = c
        self.head = nn.Sequential(
            nn.Linear(c, c), nn.BatchNorm1d(c), activation(),
            nn.Linear(c, n_outputs))

    def forward(self, x):
        h = self.mapper(self.main(self.stem(x)))
        g = h.mean(dim=2)
        g = g[:, :self.c] + g[:, self.c:].flip(1)  # invariant under reverse complement
        return self.head(g)


def build_model(n_outputs=3):
    return RCLegNet(n_outputs=n_outputs)

