# --- block: loss ---
def loss_fn(pred, target, weight):
    y = target[:, :3].float()
    w = weight.float()[:, None]
    mse = (w * (pred.float() - y) ** 2).mean()
    stash = getattr(torch, "_evoloop_hl", None)
    torch._evoloop_hl = None
    if stash is None:
        return mse
    z, lo, hi = stash
    if z.shape[0] != y.shape[0] or z.shape[1] != y.shape[1]:
        return mse
    k = z.shape[-1]
    edges = torch.linspace(lo, hi, k + 1, device=z.device, dtype=torch.float32)
    sigma = float(PARAMS.get("hl_sigma_bins", 1.5)) * (hi - lo) / k
    t = y.clamp(lo + 1e-3, hi - 1e-3)[..., None]
    cdf = 0.5 * (1.0 + torch.erf((edges - t) / (sigma * 1.41421356)))
    p = cdf[..., 1:] - cdf[..., :-1]
    p = p / p.sum(-1, keepdim=True).clamp_min(1e-8)
    ce = -(p * torch.log_softmax(z.float(), dim=-1)).sum(-1)
    return (w * ce).mean() + float(PARAMS.get("hl_mse_weight", 0.1)) * mse

# --- block: optimizer ---
def make_optimizer(model, steps_per_epoch, max_epochs):
    """AdamW with stale-ascent sharpness-aware perturbation (momentum-SAM style).
    Between optimizer steps the weights sit at w + e, with e = rho * g_prev / ||g_prev||, so each
    gradient is taken at a nearby uphill point. e is removed before every optimizer step (the update
    is applied to the clean weights) and before any eval-mode forward, so validation and the saved
    checkpoint use clean weights."""
    opt = torch.optim.AdamW(model.parameters(), lr=PARAMS["lr"], weight_decay=PARAMS["weight_decay"])
    warm = max(1, int(PARAMS["warmup_epochs"] * steps_per_epoch))
    state = {"step": 0, "active": False}
    rho = float(PARAMS.get("sam_rho", 0.05))
    params = [p for p in model.parameters() if p.requires_grad]
    eps = {}
    plateau = torch.optim.lr_scheduler.ReduceLROnPlateau(
        opt, mode="max", factor=PARAMS["plateau_factor"], patience=PARAMS["plateau_patience"])

    def _remove():
        if state["active"]:
            with torch.no_grad():
                for p in params:
                    e = eps.get(p)
                    if e is not None:
                        p.sub_(e)
            eps.clear()
            state["active"] = False

    def _pre_step(optimizer, args, kwargs):
        _remove()

    def _post_step(optimizer, args, kwargs):
        if rho <= 0 or state["step"] < warm:
            return
        with torch.no_grad():
            grads = [p.grad for p in params if p.grad is not None]
            if not grads:
                return
            norm = torch.norm(torch.stack([g.detach().float().norm() for g in grads]))
            if not torch.isfinite(norm) or norm.item() < 1e-12:
                return
            scale = rho / (norm + 1e-12)
            for p in params:
                if p.grad is None:
                    continue
                e = (p.grad.detach().float() * scale).to(p.dtype)
                p.add_(e)
                eps[p] = e
            state["active"] = True

    opt.register_step_pre_hook(_pre_step)
    opt.register_step_post_hook(_post_step)

    def _eval_hook(module, inputs):
        if not module.training and state["active"]:
            _remove()

    model.register_forward_pre_hook(_eval_hook)

    def step_fn():
        state["step"] += 1
        if state["step"] <= warm:
            for g in opt.param_groups:
                g["lr"] = PARAMS["lr"] * state["step"] / warm

    def epoch_fn(val_score):
        if state["step"] > warm:
            plateau.step(val_score)

    return opt, step_fn, epoch_fn

