def make_optimizer(model, steps_per_epoch, max_epochs):
    """Returns (optimizer, step_fn called after every batch, epoch_fn(val_score) called after every epoch).
    Keeps an EMA of all float params and buffers. A forward pre-hook puts the EMA weights into the
    model on the first eval-mode forward and puts the raw weights back on the next training forward,
    so validation, the best checkpoint and the final evaluation all use the EMA weights."""
    opt = torch.optim.AdamW(model.parameters(), lr=PARAMS["lr"], weight_decay=PARAMS["weight_decay"])
    warm = max(1, int(PARAMS["warmup_epochs"] * steps_per_epoch))
    state = {"step": 0, "n_ema": 0, "ema_loaded": False}
    plateau = torch.optim.lr_scheduler.ReduceLROnPlateau(
        opt, mode="max", factor=PARAMS["plateau_factor"], patience=PARAMS["plateau_patience"])
    base_decay = float(PARAMS.get("ema_decay", 0.999))
    sd = model.state_dict(keep_vars=True)
    tensors = {k: (v.data if hasattr(v, "data") else v) for k, v in sd.items()}
    keys = [k for k, v in tensors.items() if torch.is_floating_point(v)]
    live = [tensors[k] for k in keys]
    with torch.no_grad():
        ema = [t.detach().clone().float() for t in live]
        raw = [t.detach().clone() for t in live]

    def _ema_update():
        state["n_ema"] += 1
        n = state["n_ema"]
        d = min(base_decay, (1.0 + n) / (10.0 + n))
        with torch.no_grad():
            for e, t in zip(ema, live):
                e.mul_(d).add_(t.detach().float(), alpha=1.0 - d)

    def _hook(module, inputs):
        with torch.no_grad():
            if module.training:
                if state["ema_loaded"]:
                    for r, t in zip(raw, live):
                        t.copy_(r)
                    state["ema_loaded"] = False
            else:
                if not state["ema_loaded"] and state["n_ema"] > 0:
                    for r, e, t in zip(raw, ema, live):
                        r.copy_(t)
                        t.copy_(e.to(t.dtype))
                    state["ema_loaded"] = True
        return None

    model.register_forward_pre_hook(_hook)

    def step_fn():
        state["step"] += 1
        if state["step"] <= warm:
            for g in opt.param_groups:
                g["lr"] = PARAMS["lr"] * state["step"] / warm
        _ema_update()

    def epoch_fn(val_score):
        if state["step"] > warm:
            plateau.step(val_score)

    return opt, step_fn, epoch_fn

# --- block: model ---
class SELayer(nn.Module):
    def __init__(self, inp, oup, reduction=4):
        super().__init__()
        self.fc = nn.Sequential(
            nn.Linear(oup, inp // reduction), nn.SiLU(),
            nn.Linear(inp // reduction, oup), nn.Sigmoid())

    def forward(self, x):
        y = self.fc(x.mean(dim=2))
        return x * y.unsqueeze(-1)


class EffBlock(nn.Module):
    def __init__(self, in_ch, ks, resize_factor, activation):
        super().__init__()
        mid = in_ch * resize_factor
        self.block = nn.Sequential(
            nn.Conv1d(in_ch, mid, 1, bias=False), nn.BatchNorm1d(mid), activation(),
            nn.Conv1d(mid, mid, ks, groups=mid, padding="same", bias=False), nn.BatchNorm1d(mid), activation(),
            SELayer(in_ch, mid, reduction=4),
            nn.Conv1d(mid, in_ch, 1, bias=False), nn.BatchNorm1d(in_ch), activation())

    def forward(self, x):
        return self.block(x)


class LocalBlock(nn.Module):
    def __init__(self, in_ch, out_ch, ks, activation):
        super().__init__()
        self.block = nn.Sequential(
            nn.Conv1d(in_ch, out_ch, ks, padding="same", bias=False), nn.BatchNorm1d(out_ch), activation())

    def forward(self, x):
        return self.block(x)


class ResidualConcat(nn.Module):
    def __init__(self, fn):
        super().__init__()
        self.fn = fn

    def forward(self, x):
        return torch.cat([self.fn(x), x], dim=1)


class HistLegNet(nn.Module):
    """LegNet trunk with a histogram (HL-Gauss) output: per cell type a softmax over n_bins label
    bins on [lo, hi]. forward returns the expectation (B, n_outputs); in training the bin logits are
    left in torch._evoloop_hl for the loss. In eval, an input wider than the training width is
    averaged over crops of the training width (shift test-time augmentation of the one network)."""
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=64, stem_ks=11, ef_ks=9,
                 ef_block_sizes=(128, 160, 192, 256), pool_sizes=(2, 2, 2, 2), resize_factor=4,
                 activation=nn.SiLU, n_bins=128, lo=-4.0, hi=12.0, tta_stride=2):
        super().__init__()
        self.n_outputs = n_outputs
        self.n_bins = n_bins
        self.lo = float(lo)
        self.hi = float(hi)
        self.tta_stride = int(tta_stride)
        self.register_buffer("train_width", torch.zeros((), dtype=torch.long))
        self.stem = LocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for pool, out_ch in zip(pool_sizes, ef_block_sizes):
            blocks.append(nn.Sequential(
                ResidualConcat(EffBlock(ch, ef_ks, resize_factor, activation)),
                LocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(pool) if pool != 1 else nn.Identity()))
            ch = out_ch
        self.main = nn.Sequential(*blocks)
        self.mapper = nn.Sequential(nn.Conv1d(ch, ch * 2, 1, bias=False), nn.BatchNorm1d(ch * 2), activation())
        self.head = nn.Sequential(
            nn.Linear(ch * 2, ch * 2), nn.BatchNorm1d(ch * 2), activation(),
            nn.Linear(ch * 2, n_outputs * n_bins))
        width = (self.hi - self.lo) / n_bins
        centers = torch.linspace(self.lo + width / 2, self.hi - width / 2, n_bins)
        self.register_buffer("centers", centers)
        with torch.no_grad():
            last = self.head[-1]
            last.weight.mul_(0.1)
            prior = -0.5 * ((centers - 0.5) / 1.2) ** 2
            last.bias.copy_(prior.repeat(n_outputs))

    def _logits(self, x):
        x = self.mapper(self.main(self.stem(x)))
        z = self.head(F.adaptive_avg_pool1d(x, 1).squeeze(-1)).float()
        return z.view(-1, self.n_outputs, self.n_bins)

    def _expect(self, z):
        return (torch.softmax(z, dim=-1) * self.centers.float()).sum(-1)

    def forward(self, x):
        if self.training:
            with torch.no_grad():
                self.train_width.fill_(int(x.shape[-1]))
            z = self._logits(x)
            torch._evoloop_hl = (z, self.lo, self.hi)
            return self._expect(z)
        tw = int(self.train_width.item())
        W = int(x.shape[-1])
        if tw <= 0 or W <= tw:
            return self._expect(self._logits(x))
        m = W - tw
        stride = max(1, self.tta_stride)
        offs = list(range(0, m + 1, stride))
        if offs[-1] != m:
            offs.append(m)
        out = None
        for o in offs:
            p = self._expect(self._logits(x[..., o:o + tw]))
            out = p if out is None else out + p
        return out / len(offs)


def build_model(n_outputs=3):
    return HistLegNet(n_outputs=n_outputs)

# --- block: data_handling ---
def prepare_training_data(y, se, meta):
    """Return (row mask, training targets, per-row weights, inverse transform for predictions)."""
    keep = np.ones(len(y), bool)
    weights = np.ones(len(y), np.float32)
    return keep, y, weights, lambda p: p

# --- block: input_pipeline ---
def make_batch(x_codes, rows, train, generator=None):
    """x_codes: uint8 (N, 400) on device, insert centred. Returns (B, 4, W) float.
    Training: width 200+2*flank with a random shift of up to +-shift. Eval: the centred window
    widened by shift on each side (200+2*(flank+shift)); the model averages over its crops."""
    flank = PARAMS["flank"]
    shift = int(PARAMS["shift"])
    b = len(rows)
    dev = x_codes.device
    if train:
        width = 200 + 2 * flank
        centre = (x_codes.shape[1] - width) // 2
        if shift > 0:
            off = centre + torch.randint(-shift, shift + 1, (b,), device=dev, generator=generator)
        else:
            off = torch.full((b,), centre, device=dev)
    else:
        width = 200 + 2 * (flank + max(0, shift))
        centre = (x_codes.shape[1] - width) // 2
        off = torch.full((b,), centre, device=dev)
    cols = off[:, None] + torch.arange(width, device=dev)[None, :]
    codes = x_codes[rows[:, None], cols].long()
    if train and PARAMS["rc_aug"]:
        flip = torch.rand(b, device=dev, generator=generator) < 0.5
        codes = torch.where(flip[:, None], (3 - codes).flip(1), codes)
    return F.one_hot(codes, 4).transpose(1, 2).float()


def reverse_complement(x):
    return x.flip(1).flip(2)  # A<->T, C<->G under ACGT order, and reverse

# --- block: loss ---
def loss_fn(pred, target, weight):
    y = target[:, :3].float()
    w = weight.float()[:, None]
    mse = (w * (pred.float() - y) ** 2).mean()
    stash = getattr(torch, "_evoloop_hl", None)
    torch._evoloop_hl = None
    if stash is None:
        return mse
    z, lo, hi = stash
    if z.shape[0] != y.shape[0] or z.shape[1] != y.shape[1]:
        return mse
    k = z.shape[-1]
    edges = torch.linspace(lo, hi, k + 1, device=z.device, dtype=torch.float32)
    sigma = float(PARAMS.get("hl_sigma_bins", 1.5)) * (hi - lo) / k
    t = y.clamp(lo + 1e-3, hi - 1e-3)[..., None]
    cdf = 0.5 * (1.0 + torch.erf((edges - t) / (sigma * 1.41421356)))
    p = cdf[..., 1:] - cdf[..., :-1]
    p = p / p.sum(-1, keepdim=True).clamp_min(1e-8)
    ce = -(p * torch.log_softmax(z.float(), dim=-1)).sum(-1)
    return (w * ce).mean() + float(PARAMS.get("hl_mse_weight", 0.1)) * mse

